<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth_check.php';
require_once __DIR__ . '/../includes/functions.php';
$pageTitle='Books'; $activePage='books';
$q=trim((string)($_GET['q']??''));
$sql="SELECT b.*,c.category_name,p.publisher_name,(SELECT GROUP_CONCAT(a.author_name SEPARATOR ', ') FROM book_authors ba JOIN authors a ON a.author_id=ba.author_id WHERE ba.book_id=b.book_id) authors FROM books b JOIN categories c ON c.category_id=b.category_id LEFT JOIN publishers p ON p.publisher_id=b.publisher_id";
$params=[]; if($q!==''){$sql.=" WHERE b.title LIKE ? OR b.isbn LIKE ? OR c.category_name LIKE ? OR EXISTS(SELECT 1 FROM book_authors ba JOIN authors a ON a.author_id=ba.author_id WHERE ba.book_id=b.book_id AND a.author_name LIKE ?)";$like="%$q%";$params=[$like,$like,$like,$like];}$sql.=' ORDER BY b.title';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
require __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/navbar.php'; ?>
<main class="main-content"><header class="topbar"><div><span class="eyebrow">LIBRARY OPERATIONS</span><h1>Books</h1></div></header><section class="content-card"><?php flash_html(); ?><div class="section-heading"><div><h2>Book catalogue</h2><p>Manage titles, authors, categories and available copies.</p></div><a class="btn" href="<?=APP_URL?>/books/create.php">＋ Add book</a></div><form class="search-form" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search title, ISBN, author or category"><button class="btn">Search</button><a class="btn btn-secondary" href="index.php">Reset</a></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Cover</th><th>ISBN</th><th>Title</th><th>Author(s)</th><th>Category</th><th>Copies</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><img class="book-cover" src="<?=APP_URL?>/assets/images/book-covers/<?=rawurlencode((string)$r['isbn'])?>.jpg" alt="Cover of <?=e($r['title'])?>" loading="lazy" onerror="this.onerror=null;this.src='https://covers.openlibrary.org/b/isbn/<?=rawurlencode((string)$r['isbn'])?>-L.jpg'"></td><td><?=e($r['isbn'])?></td><td><strong><?=e($r['title'])?></strong><br><small><?=e($r['publisher_name']??'Publisher not recorded')?></small></td><td><?=e($r['authors']??'Not assigned')?></td><td><?=e($r['category_name'])?></td><td><?=e($r['available_copies'])?> / <?=e($r['total_copies'])?></td><td><a class="btn btn-small btn-secondary" href="edit.php?id=<?=(int)$r['book_id']?>">Edit</a> <form class="inline-form" method="post" action="delete.php" onsubmit="return confirm('Delete this book? Books with loan history cannot be deleted.');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['book_id']?>"><button class="btn btn-small btn-danger">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty-state">No books found.</td></tr><?php endif; ?></tbody></table></div></section></main><?php require __DIR__.'/../includes/footer.php'; ?>